export type Session = { id: string; revision: number; platform: string; activityType: string; description: string; sku: string | null; marketplaceListingId: string | null; status: string; startedAt: string; endedAt: string | null; durationSeconds: number; effectiveSeconds: number; trackingSource: string; notes: string | null };
export type Summary = { totalSeconds: number; today: Record<string, number>; byPlatform: Record<string, number>; daily: Record<string, Record<string, number>>; weekly: Record<string, Record<string, number>>; targets: { id: string; platform: string; period: string; targetMinutes: number; actualMinutes: number; percentage: number }[] };
export type Metric = { platform: string; publishedListings: number | null; averageMinutesPerListing: number | null; listingsPerHour: number | null; eligibleMinutes: number; preparationMinutes: number; publishingMinutes: number; synchronizationMinutes: number; coverage: string };
export type Credential = { id: string; name: string; expiresAt: string; revokedAt: string | null };
export type Revenue = { available: boolean; reason?: string; totals?: Record<string, number>; byPlatform?: Record<string, Record<string, number>>; daily?: Record<string, Record<string, number>>; weekly?: Record<string, Record<string, number>>; orderCount?: number; excluded?: number; definition?: string };
export type Dashboard = { summary: Summary; live: Summary; metrics: { platforms: Metric[]; definition: string }; entries: Session[]; totalEntries: number; byActivity: Record<string, number>; bySource: Record<string, number>; credentials: Credential[]; revenue: Revenue; extensionLastSync: string | null; currentManual: Session | null };
export const platformNames: Record<string, string> = { ERP: "ERP", EBAY: "eBay", ETSY: "Etsy", AMAZON: "Amazon" };
export const platformColors: Record<string, string> = { ERP: "#8b5cf6", EBAY: "#3b82f6", ETSY: "#f1641e", AMAZON: "#f59e0b" };
export const activityLabel = (value: string) => value.replaceAll("_", " ").toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
export const timeLabel = (seconds: number) => `${Math.floor(seconds / 3600)}h ${Math.floor(seconds % 3600 / 60)}m`;
export function money(value: number, currency: string) { try { return new Intl.NumberFormat("en-IN", { style: "currency", currency, maximumFractionDigits: 2 }).format(value); } catch { return `${currency} ${value.toFixed(2)}`; } }
