  {data?.currentManual && <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900"><span>An earlier manual timer is still open. Close it so it does not override automatic marketplace attribution.</span><Button size="sm" disabled={busy} variant="outline" onClick={() => run(() => api(`sessions/${data.currentManual!.id}/stop`, "POST", { revision: data.currentManual!.revision }), "Previous timer closed")}>Close previous timer</Button></div>}
