  <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[
   { label: "Active work", value: data ? timeLabel(data.summary.totalSeconds) : "—", hint: "Personal time · overlaps removed", icon: Clock3, color: "text-blue-600 bg-blue-500/10" },
   { label: "Marketplace order value", value: data?.revenue.available ? money(orderValue, selectedCurrency) : "Unavailable", hint: "Shop-wide order totals · original currency", icon: TrendingUp, color: "text-teal-600 bg-teal-500/10" },
   { label: "Orders received", value: data?.revenue.available ? String(data.revenue.orderCount || 0) : "—", hint: "Unique eligible marketplace orders", icon: ShoppingBag, color: "text-amber-600 bg-amber-500/10" },
   { label: "Confirmed publications", value: data ? String(published) : "—", hint: "Your verified ERP eBay publications", icon: Activity, color: "text-violet-600 bg-violet-500/10" },
  ].map(card => <Card key={card.label} className="rounded-2xl shadow-sm"><CardContent className="p-5"><div className="flex items-center justify-between gap-2"><p className="text-xs font-medium text-muted-foreground">{card.label}</p><span className={`rounded-lg p-2 ${card.color}`}><card.icon className="h-4 w-4" /></span></div><p className="mt-3 truncate text-2xl font-semibold tracking-tight tabular-nums">{card.value}</p><p className="mt-2 text-[11px] text-muted-foreground">{card.hint}</p></CardContent></Card>)}</div>
