  <div className="flex flex-wrap items-center justify-between gap-3"><p className="text-xs text-muted-foreground">Time charts show your activity. Order charts show marketplace-wide sales context, not an individual productivity score.</p>{currencies.length > 0 && <label className="flex items-center gap-2 text-xs">Order currency<select className="rounded-lg border bg-card p-2" value={selectedCurrency} onChange={e => setCurrency(e.target.value)}>{currencies.map(c => <option key={c}>{c}</option>)}</select></label>}</div>
