  {tab === "activity" && <Card className="rounded-2xl"><CardHeader><CardTitle className="text-base">Your activity timeline</CardTitle><p className="text-xs text-muted-foreground">Most recent {recent.length} of {data?.totalEntries || 0} intervals · displayed durations remove overlaps in the selected window</p></CardHeader><CardContent>{loading && !data ? <div className="flex justify-center py-12"><Loader2 className="animate-spin text-muted-foreground" /></div> : recent.length ? <div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-sm"><thead className="text-[11px] uppercase tracking-wider text-muted-foreground"><tr>{["Marketplace / task", "Started", "Active time", "Recorded via", ""].map((h, i) => <th className="pb-3 font-medium" key={i}>{h}</th>)}</tr></thead><tbody>{recent.map(s => <tr key={s.id} className="border-t"><td className="py-3"><div className="flex items-center gap-3"><PlatformLogo platform={s.platform} compact /><div><p className="font-medium">{s.sku || activityLabel(s.activityType)}</p><p className="mt-0.5 text-xs text-muted-foreground">{platformNames[s.platform]} · {activityLabel(s.activityType)}</p></div></div></td><td className="text-xs text-muted-foreground">{new Date(s.startedAt).toLocaleString("en-IN", { timeZone: zone, day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })}</td><td className="font-medium tabular-nums">{s.effectiveSeconds < 60 ? `${Math.floor(s.effectiveSeconds)}s` : timeLabel(s.effectiveSeconds)}</td><td><span className={`rounded-full px-2.5 py-1 text-[10px] font-medium ${s.trackingSource === "AUTOMATIC" ? "bg-blue-500/10 text-blue-600" : s.trackingSource === "EXTENSION" ? "bg-teal-500/10 text-teal-600" : "bg-muted text-muted-foreground"}`}>{s.trackingSource === "AUTOMATIC" ? "ERP automatic" : s.trackingSource === "EXTENSION" ? "Chrome estimate" : "Legacy manual"}</span></td><td className="text-right"><Button size="sm" variant="ghost" disabled={s.status !== "COMPLETED"} onClick={() => setEditing({ ...s })}>Correct</Button></td></tr>)}</tbody></table></div> : <div className="rounded-xl border border-dashed py-14 text-center"><Clock3 className="mx-auto mb-3 h-8 w-8 text-muted-foreground/40" /><p className="text-sm font-medium">Your workday starts here</p><p className="mx-auto mt-2 max-w-md text-xs leading-relaxed text-muted-foreground">Work in ERP as usual. Selecting Etsy or eBay in the listing editor switches your work context automatically. Recent intervals sync after the idle safety buffer.</p><Button asChild className="mt-5" size="sm"><Link href="/marketplace-create-listings">Go to listing workspace<ArrowRight className="h-3.5 w-3.5" /></Link></Button></div>}</CardContent></Card>}
